content.text:
{
  "primary_meaning": "Reverential awe, profound respect, and loving obedience toward God that constitutes the foundation of true wisdom, knowledge, and righteous living",
  "primary_basis": [
    "Proverbs 1:7",
    "Proverbs 9:10",
    "Psalm 111:10",
    "Job 28:28",
    "Ecclesiastes 12:13",
    "Isaiah 11:2-3"
  ],
  "alternatives": [
    {
      "meaning": "Servile terror or dread of divine wrath, punishment, and judgment",
      "basis": [
        "Hebrews 10:31",
        "passages on God's wrath and judgment (e.g., Deuteronomy 28; Revelation)",
        "distinction in classical theology between servile and filial fear"
      ],
      "prominence": "common"
    },
    {
      "meaning": "One of the seven gifts of the Holy Spirit (filial fear that perfects hope and charity)",
      "basis": [
        "Isaiah 11:2-3",
        "Catholic and Eastern Christian catechetical tradition",
        "Thomas Aquinas and scholastic treatments of the gifts"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Simple religious piety or covenantal loyalty expressed in Torah observance",
      "basis": [
        "Deuteronomy 6:2, 10:12",
        "wisdom literature framing",
        "some historical-critical readings of Hebrew yir'at YHWH"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Across Protestant, Catholic, and Orthodox teaching the dominant sense is positive reverential awe rather than mere fright; distinctions between filial and servile fear are standard but do not overturn the primary positive reading."
}
